function validate([word]) {
  if (typeof word !== 'string' || word.length < 2 || word.length > 100) return 'word needs 2 to 100 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word may only contain lowercase letters.';
  return null;
}

