function equalFrequency(word) {
  const count = new Array(26).fill(0);
  for (const ch of word) {
    count[ch.charCodeAt(0) - 97]++;
  }

  for (let letter = 0; letter < 26; letter++) {
    if (count[letter] === 0) {
      continue;
    }
    count[letter]--;
    const present = count.filter(c => c > 0);
    const allEqual = present.every(c => c === present[0]);
    count[letter]++;
    if (allEqual) {
      return true;
    }
  }
  return false;
}

