function equalFrequency(word) {
  for (let i = 0; i < word.length; i++) {
    const rest = word.slice(0, i) + word.slice(i + 1);
    const freq = new Map();
    for (const ch of rest) freq.set(ch, (freq.get(ch) || 0) + 1);
    if (new Set(freq.values()).size === 1) return true;
  }
  return false;
}

