function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const maxLen = size === 'large' ? 100 : 8;
  const shuffle = (arr) => {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  };
  for (;;) {
    const kinds = 1 + Math.floor(rand() * (size === 'large' ? 26 : 4));
    const pool = shuffle(letters.split('')).slice(0, kinds);
    const chars = [];
    const mode = rand();
    if (mode < 0.35) {
      // Random letters from a small pool.
      const n = 2 + Math.floor(rand() * (maxLen - 1));
      for (let i = 0; i < n; i++) chars.push(pool[Math.floor(rand() * kinds)]);
    } else {
      // Equal frequencies, then a small disturbance that may or may not be fixable.
      const most = Math.max(1, Math.floor((maxLen - 1) / kinds));
      const f = 1 + Math.floor(rand() * most);
      for (const ch of pool) for (let k = 0; k < f; k++) chars.push(ch);
      const twist = rand();
      if (twist < 0.4) chars.push(pool[Math.floor(rand() * kinds)]);
      else if (twist < 0.6) chars.push(letters[Math.floor(rand() * 26)]);
      else if (twist < 0.8) {
        chars.push(pool[Math.floor(rand() * kinds)]);
        chars.push(pool[Math.floor(rand() * kinds)]);
      } else if (chars.length > 2) chars.pop();
    }
    if (chars.length < 2 || chars.length > maxLen) continue;
    return [shuffle(chars).join('')];
  }
}
